--   - pico:driver-master       — Drivers (20 seeded)
--   - pico:tank-status         — Tank locations (30 seeded)
--   - pico:workflow-activity   — Recent workflow events (live audit)
--
-- Use literal JSON strings for body_json so Spring ScriptUtils can parse
-- the file as one statement per `;` line without choking on nested
-- JSON_OBJECT()/JSON_ARRAY() builders. Each statement is one logical line.
-- All idempotent via NOT EXISTS guards.
-- =====================================================================

-- 1. Entities + fields ---------------------------------------------------




-- 2. Page definitions ----------------------------------------------------

-- 3. Page versions (body_json as literal JSON string) --------------------



-- 4. Wire current_version_id ---------------------------------------------
UPDATE page_definition SET current_version_id = (SELECT id FROM page_version WHERE page_id = page_definition.id AND version = 1 LIMIT 1) WHERE tenant_id=1 AND code IN ('pico:driver-master','pico:tank-status','pico:workflow-activity') AND current_version_id IS NULL;
